// @FIGURE_CODE_BEGIN
var SVGNS = 'http://www.w3.org/2000/svg';
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 640, H = 452;
draw.viewbox(0, 0, W, H);

var RED = '#e0352b';
var BLUE = '#1a6fd4';
var GRAV = 9.8;
var M1 = 2.0;
var SCALE = 1.8;          // px per newton
var state = { m2: 4.0, phase: 'held' };
var phaseF = { 'held': 0, 'just released': 0.18, 'in motion': 0.55, 'later': 1.0 };

/* ── wood-grain pattern ─────────────────────────────────────────── */
var wood = draw.pattern(46, 16, function (add) {
  add.rect(46, 16).fill('#f9e7ce');
  add.path('M-3,4 q11,-3.5 23,0 t23,0').fill('none').stroke({ color: '#ecc79c', width: 1.3 });
  add.path('M-3,11 q11,3.5 23,0 t23,0').fill('none').stroke({ color: '#e2b788', width: 1.1 });
  add.path('M-3,15 q11,-2 23,0 t23,0').fill('none').stroke({ color: '#f0d2ad', width: 1.0 });
});

/* ── text helpers ───────────────────────────────────────────────── */
function mathText(g, x, y, main, sub, o) {
  o = o || {};
  var size = o.size || 15;
  var t = g.plain('');
  var t1 = document.createElementNS(SVGNS, 'tspan');
  t1.textContent = main;
  t1.setAttribute('font-style', o.upright ? 'normal' : 'italic');
  t.node.appendChild(t1);
  if (sub) {
    var t2 = document.createElementNS(SVGNS, 'tspan');
    t2.textContent = sub;
    t2.setAttribute('font-size', (size * 0.66).toFixed(1));
    t2.setAttribute('dy', (size * 0.24).toFixed(1));
    t.node.appendChild(t2);
  }
  t.font({ family: 'Georgia, "Times New Roman", serif', size: size, weight: o.weight || 'normal' });
  t.fill(o.fill || '#1a1a1a');
  t.attr({ x: x, y: y, 'text-anchor': o.anchor || 'middle' });
  if (o.halo !== false) {
    t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 3, 'stroke-linejoin': 'round' });
  }
  return t;
}

function plainText(g, x, y, s, size, fill, anchor, weight, style) {
  var t = g.plain(s);
  t.font({ family: 'Helvetica, Arial, sans-serif', size: size, weight: weight || 'normal', style: style || 'normal' });
  t.fill(fill || '#333');
  t.attr({ x: x, y: y, 'text-anchor': anchor || 'middle' });
  return t;
}

/* vector label (bold italic letter with an arrow drawn above it), right-aligned at xEnd */
function vecLabel(g, xEnd, yBase, main, sub, color, size) {
  mathText(g, xEnd, yBase, main, sub, { size: size, anchor: 'end', fill: color, weight: 'bold' });
  var wMain = size * 0.72, wSub = sub ? size * 0.42 : 0;
  var cx = xEnd - wSub - wMain / 2;
  var hw = wMain * 0.60;
  var by = yBase - size * 0.99;
  g.line(cx - hw, by, cx + hw - 1, by).stroke({ color: color, width: 1.3, linecap: 'butt' });
  g.polygon([cx + hw - 1, by - 2.4, cx + hw - 1, by + 2.4, cx + hw + 3.2, by].join(' ')).fill(color);
}

/* ── vertical arrow ─────────────────────────────────────────────── */
function arrowV(g, x, yFrom, yTo, color, w, hw) {
  var grp = g.group();
  var dir = yTo > yFrom ? 1 : -1;
  var hl = hw * 2.0;
  grp.line(x, yFrom, x, yTo - dir * hl * 0.85).stroke({ color: color, width: w, linecap: 'butt' });
  grp.polygon([x - hw, yTo - dir * hl, x + hw, yTo - dir * hl, x, yTo].join(' ')).fill(color);
  return grp;
}

function interactive(el, tip, title, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  if (title) el.on('click', function () { showPopup(title, body); });
  return el;
}

/* ══ STATIC SCENERY ═════════════════════════════════════════════ */
var gStatic = draw.group();
var PCX = 141, PCY = 122, RC = 52;
var CX1 = PCX - RC, CX2 = PCX + RC;
var Y1_0 = 238, Y2_0 = 330, BS = 80;

/* ceiling beam */
gStatic.rect(196, 24).move(58, 0).fill('#f7e3c1').stroke({ color: '#e5cda4', width: 1 });
gStatic.rect(196, 8).move(58, 24).fill('#ecd7b0').stroke({ color: '#e0c69c', width: 1 });
/* bolts */
[104, 168].forEach(function (bx) {
  gStatic.rect(15, 11).move(bx - 7.5, 31).radius(2).fill('#bdbdbd').stroke({ color: '#9a9a9a', width: 1 });
  gStatic.rect(9, 4).move(bx - 4.5, 29).radius(1.5).fill('#d6d6d6');
});
/* stem */
gStatic.rect(19, 96).move(PCX - 9.5, 30).fill('#b4b4b4').stroke({ color: '#8e8e8e', width: 1 });
gStatic.rect(4, 94).move(PCX - 6, 31).fill('#dcdcdc').opacity(0.85);

/* pulley */
var gPulley = gStatic.group();
gPulley.circle(RC * 2).center(PCX, PCY).fill('#8e8e8e').stroke({ color: '#787878', width: 1 });
gPulley.circle(47 * 2).center(PCX, PCY).fill('#c3c3c3').stroke({ color: '#a2a2a2', width: 1 });
gPulley.circle(40 * 2).center(PCX, PCY).fill('#9f9f9f').stroke({ color: '#8a8a8a', width: 1 });
gPulley.circle(24 * 2).center(PCX, PCY).fill('#c7c7c7').stroke({ color: '#a6a6a6', width: 1 });
gPulley.circle(15 * 2).center(PCX, PCY).fill('#909090').stroke({ color: '#7a7a7a', width: 1 });
gPulley.circle(14).center(PCX, PCY).fill('#5d5d5d');
interactive(gPulley, 'Frictionless, massless pulley', 'Frictionless pulley',
  'An ideal pulley has no friction and no rotational inertia, so it only changes the direction of the cord. It does not change the size of the pull, which is why the tension is exactly the same in the segment holding m\u2081 and the segment holding m\u2082.');

/* cord over the groove (drawn on top of the wheel) */
var cordArc = gStatic.path('M' + CX1 + ',' + PCY + ' A' + RC + ',' + RC + ' 0 0 1 ' + CX2 + ',' + PCY)
  .fill('none').stroke({ color: '#e6c56b', width: 3.6, linecap: 'round' });

/* dynamic layers */
var gRefs = draw.group();
var gCord = draw.group();
var gBlocks = draw.group();
var gFBD = draw.group();

/* ── free-body static frame ─────────────────────────────────────── */
var B1X = 398, B2X = 560, FB_TOP = 165, FB_BOT = 235, FBS = 70;
plainText(gStatic, B1X, 24, 'Block 1', 15, '#2b2b2b', 'middle', 'bold');
plainText(gStatic, B2X, 24, 'Block 2', 15, '#2b2b2b', 'middle', 'bold');

/* legend */
var gLeg = gStatic.group();
gLeg.line(332, 434, 350, 434).stroke({ color: RED, width: 4 });
gLeg.polygon('350,430 350,438 357,434').fill(RED);
plainText(gLeg, 361, 437.5, 'force vectors', 10, '#666', 'start');
gLeg.line(440, 434, 456, 434).stroke({ color: BLUE, width: 2.4 });
gLeg.polygon('456,430.8 456,437.2 462,434').fill(BLUE);
plainText(gLeg, 466, 437.5, 'acceleration', 10, '#666', 'start');
plainText(gLeg, 332, 449, 'the two T arrows are always drawn identical', 9.5, '#8a8a8a', 'start', 'normal', 'italic');

/* ══ REDRAW ═════════════════════════════════════════════════════ */
function redraw() {
  var m2 = state.m2;
  var a = (m2 - M1) * GRAV / (M1 + m2);
  var T = 2 * M1 * m2 * GRAV / (M1 + m2);
  var w1 = M1 * GRAV, w2 = m2 * GRAV;

  /* ---- pictorial ---- */
  gRefs.clear(); gCord.clear(); gBlocks.clear();
  var d = phaseF[state.phase] * 60 * (a / GRAV);
  if (d > 36) d = 36;
  var y1 = Y1_0 - d, y2 = Y2_0 + d;

  if (d > 0.5) {
    gRefs.line(36, Y1_0, 252, Y1_0).stroke({ color: '#c3c3c3', width: 1, dasharray: '5,4' });
    gRefs.line(36, Y2_0, 252, Y2_0).stroke({ color: '#c3c3c3', width: 1, dasharray: '5,4' });
    plainText(gRefs, 36, Y1_0 - 4, 'start', 9, '#b0b0b0', 'start');
    plainText(gRefs, 36, Y2_0 - 4, 'start', 9, '#b0b0b0', 'start');
  }

  var c1 = gCord.line(CX1, PCY, CX1, y1).stroke({ color: '#e6c56b', width: 3.4 });
  var c2 = gCord.line(CX2, PCY, CX2, y2).stroke({ color: '#e6c56b', width: 3.4 });
  [c1, c2].forEach(function (c) {
    interactive(c, 'One inextensible cord \u2014 one tension', 'A single cord',
      'Because the cord cannot stretch, whatever length m\u2082 descends, m\u2081 must rise. That geometric link forces the two speeds, and the two accelerations, to have the same magnitude and opposite directions.');
  });

  var b1 = gBlocks.rect(BS, BS).move(CX1 - BS / 2, y1).radius(2).fill(wood).stroke({ color: '#9d9d9d', width: 1.4 });
  var b2 = gBlocks.rect(BS, BS).move(CX2 - BS / 2, y2).radius(2).fill(wood).stroke({ color: '#9d9d9d', width: 1.4 });
  interactive(b1, 'm\u2081 = ' + M1.toFixed(1) + ' kg (lighter \u2014 rises)', null, null);
  interactive(b2, 'm\u2082 = ' + m2.toFixed(1) + ' kg' + (m2 > M1 ? ' (heavier \u2014 descends)' : ''), null, null);
  mathText(gBlocks, CX1 - BS / 2 - 8, y1 + BS / 2 + 5, 'm', '1', { size: 16, anchor: 'end' });
  mathText(gBlocks, CX2 + BS / 2 + 8, y2 + BS / 2 + 5, 'm', '2', { size: 16, anchor: 'start' });

  /* ---- free-body diagrams ---- */
  gFBD.clear();
  var tLen = T * SCALE, w1Len = w1 * SCALE, w2Len = w2 * SCALE;
  var aLen = 70 * (a / GRAV);

  [[B1X, 'm', '1', tLen, w1Len, 'w', '1', w1, -1],
   [B2X, 'm', '2', tLen, w2Len, 'w', '2', w2, 1]].forEach(function (cfg) {
    var cx = cfg[0], sub = cfg[2], wLen = cfg[4], wVal = cfg[7], aDir = cfg[8];

    var blk = gFBD.rect(FBS, FBS).move(cx - FBS / 2, FB_TOP).radius(2)
      .fill(wood).stroke({ color: '#9d9d9d', width: 1.4 });
    interactive(blk, 'Block ' + sub + ':  m = ' + (sub === '1' ? M1 : state.m2).toFixed(1) + ' kg', null, null);
    mathText(gFBD, cx - FBS / 2 - 10, FB_TOP + FBS / 2 + 5, 'm', sub, { size: 16, anchor: 'end' });

    /* tension: always identical length on both blocks */
    var ta = arrowV(gFBD, cx, FB_TOP, FB_TOP - tLen, RED, 4.5, 6);
    interactive(ta, 'T = ' + T.toFixed(1) + ' N  (same on both blocks)', 'One cord \u2192 one tension',
      'Both blocks are pulled by the same cord passing over a frictionless pulley, so the magnitude of the tension is identical for m\u2081 and m\u2082: T = 2m\u2081m\u2082g/(m\u2081+m\u2082) = ' + T.toFixed(1) + ' N. Notice the two T arrows never differ in length, no matter how you set the masses.');
    vecLabel(gFBD, cx - 11, FB_TOP - tLen / 2 + 5, 'T', null, RED, 16);

    /* weight */
    var wa = arrowV(gFBD, cx, FB_BOT, FB_BOT + wLen, RED, 4.5, 6);
    interactive(wa, 'w' + sub + ' = m' + sub + 'g = ' + wVal.toFixed(1) + ' N', 'Weight',
      'The weight of this block is w = mg = ' + wVal.toFixed(1) + ' N. The weights are unequal whenever the masses are, and it is exactly this difference of weights \u2014 not the tension \u2014 that drives the system.');
    vecLabel(gFBD, cx - 11, FB_BOT + wLen * 0.62, 'w', sub, RED, 16);

    /* acceleration */
    if (phaseF[state.phase] > 0 && aLen > 1.5) {
      var ax = cx + FBS / 2 + 15;
      var ymid = FB_TOP + FBS / 2;
      var aa = arrowV(gFBD, ax, ymid - aDir * aLen / 2, ymid + aDir * aLen / 2, BLUE, 2.6, 4.5);
      interactive(aa, 'a = ' + a.toFixed(2) + ' m/s\u00b2 ' + (aDir > 0 ? 'downward' : 'upward'),
        'Equal and opposite accelerations',
        'Applying Newton\u2019s second law to each block and eliminating the shared tension gives a = (m\u2082 \u2212 m\u2081)g/(m\u2081 + m\u2082) = ' + a.toFixed(2) + ' m/s\u00b2. Both arrows have the same length: the blocks accelerate equally, in opposite directions.');
      mathText(gFBD, ax + 9, ymid + 5, 'a', null, { size: 14, anchor: 'start', fill: BLUE, weight: 'bold' });
    }
  });

  /* readout */
  var ro = document.getElementById('readout');
  if (ro) {
    ro.innerHTML =
      'T&nbsp;&nbsp;= ' + T.toFixed(1) + ' N &nbsp;(both blocks)<br>' +
      'w\u2081 = ' + w1.toFixed(1) + ' N&nbsp;&nbsp;w\u2082 = ' + w2.toFixed(1) + ' N<br>' +
      'w\u2082 \u2212 w\u2081 = ' + (w2 - w1).toFixed(1) + ' N<br>' +
      'a&nbsp;&nbsp;= ' + a.toFixed(2) + ' m/s\u00b2';
  }
}

/* ══ CONTROLS ═══════════════════════════════════════════════════ */
function update_massRatio(v) {
  state.m2 = v;
  redraw();
}

function set_releasePhase(s) {
  state.phase = s;
  var btns = document.querySelectorAll('#ui button[data-phase]');
  for (var i = 0; i < btns.length; i++) {
    btns[i].classList.toggle('active', btns[i].getAttribute('data-phase') === s);
  }
  redraw();
}

/* ══ DEMO STEPS ═════════════════════════════════════════════════ */
var steps = [
  { title: 'Equal masses: balanced', narration: 'With m\u2082 set equal to m\u2081, the two weight arrows are the same length and the system hangs still. Both tension arrows are drawn identical \u2014 and each one exactly cancels its block\u2019s weight.', state: { massRatio: 2, releasePhase: 'held' } },
  { title: 'Make m\u2082 heavier', narration: 'Increase m\u2082 and watch only the w\u2082 arrow lengthen; the two T arrows stay the same length because one cord carries one tension. Block 2\u2019s downward arrow now outweighs its tension while block 1\u2019s tension outweighs its weight.', state: { massRatio: 4, releasePhase: 'held' } },
  { title: 'Release', narration: 'Let go: the unbalanced force on each block sets the system moving. Acceleration arrows appear \u2014 downward on m\u2082, upward on m\u2081, with identical length.', state: { massRatio: 4, releasePhase: 'just released' } },
  { title: 'Equal and opposite motion', narration: 'As the cord runs over the pulley, m\u2082 descends exactly as far as m\u2081 rises. Their accelerations are equal in magnitude and opposite in direction, a = (m\u2082 \u2212 m\u2081)g / (m\u2081 + m\u2082).', state: { massRatio: 4, releasePhase: 'in motion' } },
  { title: 'Push the difference further', narration: 'Increase m\u2082 toward 8 kg: the weights diverge more, the acceleration arrows grow toward g, and the blocks separate faster \u2014 yet the single tension shared by both blocks remains one common value.', state: { massRatio: 8, releasePhase: 'later' } }
];
var stepIdx = 1;

function applyStep(i) {
  stepIdx = (i % steps.length + steps.length) % steps.length;
  var s = steps[stepIdx];
  var inp = document.getElementById('massRatioInput');
  if (inp) inp.value = s.state.massRatio;
  var out = document.getElementById('massRatioVal');
  if (out) out.value = (+s.state.massRatio).toFixed(1);
  state.m2 = +s.state.massRatio;
  set_releasePhase(s.state.releasePhase);
  var nar = document.getElementById('demoNarration');
  if (nar) nar.textContent = s.narration;
  var lab = document.getElementById('stepLabel');
  if (lab) lab.textContent = (stepIdx + 1) + '/' + steps.length + ' \u00b7 ' + s.title;
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

/* initial state == blueprint defaults (m\u2082 = 4 kg, held) */
applyStep(1);

window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: In an Atwood machine two masses joined by one cord over a frictionless pulley share a single string tension, so it is the difference in their weights — not the tension — that produces a common acceleration, equal in magnitude and opposite in direction for the two blocks.
KEY INSIGHT (what students should walk away understanding): One cord means one tension acting equally on both blocks — so the acceleration comes entirely from the difference of the weights, and the two blocks must accelerate by the same amount in opposite directions.
DEMO STEPS: 5 guided steps — implement the step player in #ui

FULL BLUEPRINT:
