function mathText(g, x, y, main, sub, o) {
  o = o || {};
  var size = o.size || 16;
  var ws = 0;
  if (sub) {
    var ts = g.plain(sub)
      .font({ family: 'Georgia, "Times New Roman", serif', size: size * 0.66, style: 'italic' })
