    halo(ts);
    ws = ts.bbox().width;
    ts.attr({ x: (o.anchor === 'end') ? x - ws : x + size * 0.72 });
  }
  var tm = g.plain(main)
    .font({ family: 'Georgia, "Times New Roman", serif', size: size, style: 'italic' })
    .fill(o.fill || INK)
    .attr({ x: (o.anchor === 'end') ? x - ws : x, y: y, 'text-anchor': (o.anchor === 'end') ? 'end' : 'start' });
  halo(tm);
  return tm;
}

function plainText(g, x, y, s, size, fill, anchor, weight, style) {
  var t = g.plain(s);
  t.font({ family: 'Helvetica, Arial, sans-serif', size: size, weight: weight || 'normal', style: style || 'normal' });
  t.fill(fill || '#333');
  t.attr({ x: x, y: y, 'text-anchor': anchor || 'middle' });
  return t;
}

/* bold upright serif vector label with an over-arrow, right edge at xRight */
function vecLabel(g, xRight, yBase, main, sub, size, col) {
  col = col || INK;
