  if (sub) {
    var ts = g.plain(sub)
      .font({ family: 'Georgia, "Times New Roman", serif', size: size * 0.66, weight: 'bold' })
      .fill(col).attr({ x: xRight, y: yBase + size * 0.25, 'text-anchor': 'end' });
    halo(ts);
    ws = ts.bbox().width + 0.5;
  }
  var tm = g.plain(main)
    .font({ family: 'Georgia, "Times New Roman", serif', size: size, weight: 'bold' })
    .fill(col).attr({ x: xRight - ws, y: yBase, 'text-anchor': 'end' });
  halo(tm);
  var b = tm.bbox();
  var x0 = b.x + 1.2, x1 = b.x2 - 0.6, by = b.y - 2.2;
  g.line(x0, by, x1, by).stroke({ color: col, width: 1.5, linecap: 'butt' });
  g.polygon([x1 - 0.5, by - 2.6, x1 - 0.5, by + 2.6, x1 + 3.6, by].join(' ')).fill(col);
  return tm;
}

/* ── vertical arrow ─────────────────────────────────────────────── */
function arrowV(g, x, yFrom, yTo, color, w, hw) {
  var grp = g.group();
