  var hl = hw * 2.0;
  grp.line(x, yFrom, x, yTo - dir * hl * 0.8).stroke({ color: color, width: w, linecap: 'butt' });
  grp.polygon([x - hw, yTo - dir * hl, x + hw, yTo - dir * hl, x, yTo].join(' ')).fill(color);
  return grp;
}

